<x-app-layout>
    <div class="max-w-xl mx-auto py-12 px-6"><div class="dd-paper rounded-2xl border border-[#eadfce] p-7 shadow-sm"><p class="dd-gold uppercase tracking-[.25em] text-xs">Almost there</p><h1 class="dd-serif text-4xl text-[#3f2b1a] mt-2">Delivery Address</h1><p class="text-sm text-[#756653] mt-3">Complete your details, then pay securely with Razorpay.</p>
        <form id="checkout-form" class="space-y-4 mt-7">@csrf
            <input name="line1" placeholder="Address line 1" required class="w-full border-[#ddcfba] rounded p-3 text-sm"><input name="line2" placeholder="Address line 2 (optional)" class="w-full border-[#ddcfba] rounded p-3 text-sm"><div class="flex gap-4"><input name="city" placeholder="City" required class="w-full border-[#ddcfba] rounded p-3 text-sm"><input name="state" placeholder="State" required class="w-full border-[#ddcfba] rounded p-3 text-sm"></div><div class="flex gap-4"><input name="postal_code" placeholder="Postal code" required class="w-full border-[#ddcfba] rounded p-3 text-sm"><input name="phone" placeholder="Phone" required class="w-full border-[#ddcfba] rounded p-3 text-sm"></div><div class="border-t border-[#eadfce] pt-5 mt-6 flex justify-between text-lg"><span>Total</span><strong class="text-[#b57a24]">₹{{ number_format($total / 100, 2) }}</strong></div><p id="payment-error" class="hidden rounded bg-red-100 text-red-800 p-3 text-sm"></p><button id="pay-button" type="submit" class="w-full bg-[#315a2a] text-white py-4 rounded font-semibold text-sm hover:bg-[#24471f]">Pay with Razorpay →</button>
        </form>
    </div></div>
    <script src="https://checkout.razorpay.com/v1/checkout.js?v=20260827"></script><script>
        const checkoutForm = document.getElementById('checkout-form'), payButton = document.getElementById('pay-button'), paymentError = document.getElementById('payment-error'), csrf = document.querySelector('meta[name="csrf-token"]').content;
        const showPaymentError = (message) => { paymentError.textContent = message; paymentError.classList.remove('hidden'); payButton.disabled = false; payButton.textContent = 'Try Again →'; };
        const requestJson = async (url, options) => { const controller = new AbortController(); const timeout = setTimeout(() => controller.abort(), 15000); try { const response = await fetch(url, {...options, signal: controller.signal}); const data = await response.json().catch(() => ({})); return {response, data}; } catch (error) { if (error.name === 'AbortError') throw new Error('The payment request timed out. Please try again.'); throw error; } finally { clearTimeout(timeout); } };
        checkoutForm.addEventListener('submit', async (event) => { event.preventDefault(); paymentError.classList.add('hidden'); payButton.disabled = true; payButton.textContent = 'Preparing secure payment...';
            try { const localResult = await requestJson('{{ route('checkout.store') }}', {method:'POST', headers:{'X-CSRF-TOKEN':csrf,'Accept':'application/json'}, body:new FormData(checkoutForm)}); const localOrder = localResult.data; if (!localResult.response.ok) throw new Error(localOrder.message || 'Please check your delivery details.');
                const razorpayResult = await requestJson('{{ route('api.create-order') }}', {method:'POST', headers:{'X-CSRF-TOKEN':csrf,'Content-Type':'application/json','Accept':'application/json'}, body:JSON.stringify({amount:localOrder.amount,currency:localOrder.currency,receipt:'order_'+localOrder.local_order_id})}); const razorpayOrder = razorpayResult.data; if (!razorpayResult.response.ok) throw new Error(razorpayOrder.message || 'Unable to start payment.'); if (typeof Razorpay === 'undefined') throw new Error('Razorpay Checkout could not load. Check your internet connection and try again.');
                const options = {key:@json(config('services.razorpay.key_id')), amount:razorpayOrder.amount, currency:razorpayOrder.currency, name:'Desi Dhaani', description:'Traditional Rajasthan products', order_id:razorpayOrder.order_id, prefill:{name:@json(auth()->user()->name),email:@json(auth()->user()->email)}, theme:{color:'#315a2a'}, handler:async function(response){ try { const verification=await requestJson('{{ route('api.verify-payment') }}',{method:'POST',headers:{'X-CSRF-TOKEN':csrf,'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify(response)}); const result=verification.data; if(!verification.response.ok || !result.success) throw new Error(result.message || 'Payment verification failed.'); window.location.href='{{ url('/checkout/success') }}/'+result.order_id; } catch(error) { showPaymentError(error.message || 'Payment verification failed.'); } }, modal:{ondismiss:()=>showPaymentError('Payment was cancelled. You can try again whenever you are ready.')} };
                const razorpay = new Razorpay(options); razorpay.on('payment.failed', response => showPaymentError(response.error?.description || 'Payment failed. Please try again.')); razorpay.open(); payButton.disabled=false; payButton.textContent='Pay with Razorpay →';
            } catch(error) { showPaymentError(error.message || 'Something went wrong. Please try again.'); }
        });
    </script>
</x-app-layout>
